  showSearchBounds(bounds){if(!this.renderer)return;this.selectionBounds=bounds;if(this.selectionOutline){this.world.remove(this.selectionOutline);this.selectionOutline.geometry.dispose();this.selectionOutline.material.dispose();this.selectionOutline=null;}if(!bounds)return;const points=[],steps=24;for(let edge=0;edge<4;edge++)for(let i=0;i<=steps;i++){const t=i/steps;let lat,lon;if(edge===0){lat=bounds.north;lon=bounds.west+(bounds.east-bounds.west)*t;}else if(edge===1){lat=bounds.north+(bounds.south-bounds.north)*t;lon=bounds.east;}else if(edge===2){lat=bounds.south;lon=bounds.east+(bounds.west-bounds.east)*t;}else{lat=bounds.south+(bounds.north-bounds.south)*t;lon=bounds.west;}points.push(surfacePoint('earth',lat,lon,this.dems?.get('earth'),.01));}this.selectionOutline=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:'#77e3d5',transparent:true,opacity:.92,depthWrite:false}));this.selectionOutline.visible=this.body==='earth';this.world.add(this.selectionOutline);}
